import{_ as a,c as e,o as s,af as t}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"说卦传","description":"周易尚氏学 - 说卦传","frontmatter":{"title":"说卦传","description":"周易尚氏学 - 说卦传"},"headers":[],"relativePath":"zh/classics/shangshi/072.md","filePath":"zh/classics/shangshi/072.md"}'),r={name:"zh/classics/shangshi/072.md"};function i(n,p,c,_,o,l){return s(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="说卦传" tabindex="-1">说卦传 <a class="header-anchor" href="#说卦传" aria-label="Permalink to “说卦传”">​</a></h1><p>昔者圣人之作易也。幽赞于神明而生蓍。参天两地倚数。</p><p>案参两之说。先儒不同。马融王肃。并云天数五。地数 五。五位相合。以阴从阳。天得三合。谓一三与五也。地得 两合。谓二与四也。郑玄云。天地之数。备于十。乃参之以 天。两之以地。而倚乇（左言）大衍之数五十也。必三之以天。两之 以地者。天三覆。地二载。必极于数。庶得吉凶之审。虞翻 云。谓分天象为三才。以地两之。立六画之数。倚。马融训 依。虞王训立。按参两者乃数之本原。马王谓一三五为参 天。二四为两地。夫一二三四五乃生数。故数止于五。五数既立。以此为本。加一为六。二为七。三为八。四为九。而 蓍数乃出。然则六七八九之成数。皆原于一二三四之生数。 故曰倚数。言数皆依此立也。马王之说是也。天奇地耦。大 行五十。两地也。用四十有九。参天也。分二。两地。挂一 参天。揲四两地。归奇参天。三变得三奇。三三而九。参天 也。三变得三耦。二三得六。两地也。三变而两奇一耦。则 为人。两地也。两耦一奇则为七。参天也。盖欲知来。必先 极数。而极数之法。必参两回互。以此为本也。</p><p>观变于阴阳而立卦。发挥于刚柔而生支。和顺于道 德。而理于义。穷理尽性以至于命。昔者圣人之作 易也。将以顺性命之理。是以立天之道。曰阴与阳。 立地之道。曰柔与刚。立人之道。曰仁与义。兼三 才而两之。故易六画而成卦。分阴分阳。迭用柔刚。 故易六位而成章。</p><p>一三五阳。二四六阴。柔交居阴位。刚爻居阳位。则当 位。否则失位。以此为用。虞翻曰。和顺谓坤。道德谓乾。 以乾通坤。谓之理义。以乾推坤。谓之穷理。以坤变乾。谓 之尽性。性尽理穷。故至于命。巽为命也。</p><p>天地定位。山泽通气。雷风相薄。水火不相射。八 卦相错。数往者顺。知来者运。是故易逆数也。</p><p>此先天卦位也。天地定位。言乾位南坤位北也。薄人 也。射厌也。错妗也。交也。言八卦方位。阳错阴。阴错 阳。无一卦不相对。无一爻不相交也。此纯指先天八卦之方 位形式。故特申之曰八卦相错。太玄玄告准说卦者也。玄告 云天地相对。日月相刿。山川相流。轻重相浮。又曰南北定位。东西通气。万物错处于其中。按天地相对。南北定位。即谓乾南坤北也。日日月相会。东西通气。谓离东坎西也。天地水火。四正卦也。曰山川相流。轻重相浮。万物锗处于其中。即谓四隅卦也。正释此也。又乾凿度曰。其位也天在 上。地在下。君南臣北。父坐子伏。易若以坤西南乾西北为定位。尚得谓天在上。地在下乎。尚得谓君南臣北乎。当然 别有所指。乾凿度又云。天地之道立。山泽雷风水火之象定矣。其散布用事也。震生物于东方。离长之于南方。兑收之 于西方。坎藏之于北方。与下帝出乎震之方位同。夫曰散布用事。则震东兑西。离南坎北。未用事之先。不在此也明矣。乾凿度于乾南坤北。变为离南坎北之故。言之可谓悉。数往者顺。谓四阳卦。知来者逆。谓四阴卦。阳性强健其动 直。自内往外。顺行。放日数往者顺。阴性敛啬闭藏。自外 来内。逆行。故曰知来者逆。逆迎也。阳往阴来。自然相遇。相遇然后相交。易道乃成。故曰易逆数也。言阳逆阴。阴逆阳。故能定位通气相薄不相射也。此仍言八卦相错之理。相错故阴阳能相逆。不相错则阴自阴阳自阳。胡能相值而相交哉。</p><p>雷以动之。风以散之。雨以润之。日以暄之。艮以止之。兑以说之。乾以君之。坤以藏之。</p><p>匹耦对举。与前节位同。不过先六子后父母耳。</p><p>帝出乎震。齐乎巽。相见乎离。致役乎坤。说言乎兑。战乎乾。劳乎坎。成言乎艮。</p><p>马国翰曰。此连山易文。见乾宝周礼注引。按此言后天卦位。周易用之。恐人不知。故下节即连山易文。逐字逐句。而详释其义。并明指其方位。以见与上文所言方位。绝不同也。帝神也。即主宰万物者也。旧解皆忽略下节乃解释此节。致此节皆成赘文。</p><p>万物出乎震。震东方也。齐乎巽。巽东南也。齐也者。言万物之洁齐也。离也者明也。万物皆相见。南方之卦也。圣人南面而听天下。晌明而治。盖取诸此也。坤也者地也。万物皆致养焉。故曰致役乎坤。兑正秋也。万物之所说也。故曰说言乎兑。战乎乾。乾西北之卦也。言阴阳相薄也。坎者水也。正北方之卦也。劳卦也。万物之所归也。故曰劳平坎。艮东北之卦也。万物之所成终而所成始也。故 曰成言乎艮。</p><p>归藏也。至冬则万物皆归命于坎。故曰劳卦。坤象传云。乃终有庆。终谓亥。万物终于亥。艮先天居之。故曰成终。万物生于寅。艮后天居之。故曰成始。其以丑为岁终。寅为岁始。说此者虽巧合。然违易理。易之计岁。以冬至为界。过冬至两月。而犹曰终万物可乎。</p><p>神也者。妙万物而为言者也。动万物者。莫疾手雷。挠万物者。莫疾乎风。燥万物者。莫叹乎火。说万物者。莫说乎泽。润万物者。莫润乎水。终万物始万物者。莫盛乎艮。故水火相逮。雷风不相悖。山泽通气。然后能变化既成万物也。</p><p>来知德曰。此专明六子之功用。然孤阳孤阴。不能生物。必依先天卦位。使六子相错相交。然后能变化既成万物也。</p><p>乾健也。坤顺也。震动也。巽入也。坎陷也。离丽也。艮上也。兑说也。</p><p>此言八卦之性情。</p><p>乾为马。坤为牛。震为龙。巽为鸡。坎为豕。离为鸡。艮为狗。兑为羊。</p><p>此所谓远取诸物。巽为难。九家云。应八风也。风应节而变，变不失时。难时至而鸣。与风相应。杭辛齐曰。鸡善伏。按巽为伏。然上两解皆未必协。则谓其义至今未明可也。兑为羊。纯取其形似。旧解谓羊性狠者非也。</p><p>乾为首。坤为腹。震为足。巽为股。坎为耳。离为目。艮为手。兑为口。</p><p>此近取诸身。坎窖也。故为耳。经以兑为耳。皆取其形。旧解谓坎北方属肾。肾主耳。又谓坎北方主聪。故为耳。皆非。以上二十四象。昔人谓之本象。</p><p>乾天也。故称乎父。坤地也。故称乎母。震一索而得男。故谓之长男。巽一索而得女。故谓之长女。坎再索而得男。故谓之中男。离再索而得女。故谓之中女。艮三索而得男。故谓之少男。兑三索而得女。故谓之少女。</p><p>索求也。阴与阳互相求。文言曰。同声相应。同气相求。是也。阳求阴得三男。阴求阳得三女。而以初中上三爻为次序。实经之所用。不与尽同。如随以震为小子。艮为丈夫。大过以巽为女妻。以兑为老妇。与此正相反。盖以二人言。先生者为长。次为幼。而以一人言。则初爻为幼。至上而老矣。此其理除焦氏易林外。余无知者。易林以兑为老妇。巽为少齐。初读之皆莫明其义。后乃恍然知其悉本于易也。朱子谓说卦之象。求之于经。亦不尽合。读哉其有不合。盖说卦乃自古相传之象。至周易愈演愈精。故经所用象。不尽与说卦同。虞翻等必执说卦以解经。至大过创为二应上。初应五之恶例。以求其合。其误遂不可言矣。</p><p>乾为天。为圜。 为君。为父。为玉。为金。为寒。为冰。为大赤。为良马。为老马。为瘠马。为驳马。为木果。</p><p>为龙。为直。为衣。为言。依九家本增。下同。金玉象其纯粹。西北不同风。阴寒之地。故为寒冰。乾舍于离。南方火。故为大赤。乾健故为马。凡物皆有初壮究。故由良马而老而瘠而驳。木果形皆圜。无他义。其以驳为食虎豹之兽。或又本陆机诗疏。谓驳为木皆非。乾上放为衣。</p><p>坤为地。为母。为布。为釜。为吝啬。为均。为子母牛。为大舆。为文。为众。为柄。其于地也为黑。</p><p>为牝。为迷。为方。为囊。为棠。为黄。为帛。为浆。坤德偏布万物以致养。故为布。外府注云。布泉也。凡钱藏者曰泉。行者曰布。取名于水泉。其流行无不偏。按本为水。故象泉布。万物资地成熟。故为釜。坤闭故吝啬。不择而生故为均。坤为牛。地生生不已。今之童牛。不日又生子而为母矣。故为子母牛。万物依之为本故为柄。坤文故为帛。坤为水。故为浆。</p><p>震为雷。为龙。为玄黄。为敷。为大涂。为长子。为决躁。为苍茛竹。为萑苇。其于马也为善呜。为馵足。为作足。为的颡。其于稼也为反生。其究为健。为蕃鲜。</p><p>为玉。为鹄。为鼓。龙马（右龙）通。而马（右龙）与龙通。说文龙多毛犬也。郑作龙。云取日出色。虞作马（右龙）。云苍色。案周礼秋官犬人。掌犬牲。凡几珥沈辜用马（右龙）。注。故书马（右龙）作龙。疏杂色牲。即杂色犬牲也。又春官牧人职。用马（右龙）。御史职马（右龙）车。注皆云。故书马（有龙）作龙。是马（右龙）古作龙。清儒依虞说。多从马（右龙）。岂知龙马（右龙）音同通用。龙即马（右龙）。非误字也。特诂为龙或只诂为杂色。不诂为犬牲则误耳。又易林夬之屯云。龙吠有威。行者留止。巽寡发。震多毛。震为威。为鸣。故为龙。是郑读与焦同。敷乾宝。敷为花貌。易林亦以震为花。此象卦形。余说皆误。九家云苍茛青也。震为周为虚。归妹上六承虚筐也竹与崔苇皆有节。下阳象之。上二阴象其圆而中空。马足白为马（？）。阳在下故足白。的颡白颠也。初阳生。故曰反生。宋衷曰。阴在上。阳在下。故为反生。谓集豆之类。皆戴甲而生。按来注最为精切。格物微。取象之妙人微。而经生知之者寡。阳息至三。乾健。反复成巽。龚为垣庸。故为蕃。蕃藩通。诗小雅营营青蝇。止于蕃。是也。巽为寡。故为鲜。诗终鲜兄弟。传鲜寡也。玉色白或青。故为玉。有谓为王之讹者。证以易林象。非也。鹄鹤古通。为声音故为鼓。</p><p>巽为木。为风。为长女。为绳直。为工。为白。为长。为高。为进退。为不果。为臭。其于人也为寡发。为广颡。为多白眼。为近利市三倍。其究为躁卦。</p><p>为杨。为鹳。</p><p>陆绩云。风。士气也。巽坤之所生。故为风。故易林亦以坤为风巽柔故为绳。巽风故直。工。说文巧饰也。象人有规 。徐楷（左金）曰。为巧必遵规 法度。然后为工。按巽为顺。能顺规 。遵循法度。故为工。风可进可退。故不果。经屡以巽为疑。同此也。臭。气也。风散则气至。故为臭。巽陨落。故寡发。震为发。反巽故寡发。广颡取上二阳象。多白眼。按离为目。中爻阴。黑睛。上下阳目中之白。今二阳皆在上。睛伏在下。故多白眼。利市三倍。似取流通。或取人义。究为震。故曰躁卦。</p><p>坎为水。为沟渎。为隐伏。为矫。为弓轮。其于人也。为加优。为心病。为耳痛。为血卦。为赤。其于马也。为美脊。为亟心。为下首。为薄蹄。为曳。其于舆也。为多青。为通。为月。为盗。其于木也。为坚多心。</p><p>为宫。为律。为可。为栋。为丛棘。为狐。为蒺藜。为桎梏。为隐伏。为忧。为心病。为美脊。为亟心。为通。为坚多心。皆以阳在阴中而取象。以乾辟坤。故为沟读。曲者使直为矫。直者使曲为。水性可曲可直也。可曲故可为弓轮。水在地。犹人之有血。乾大赤。坎得乾之中爻。故亦为赤。月者水之精。故坎为月。为忧故下首。下首犹低头也。坎隐伏。故为盗。坎为屋极。故为宫。为栋。坎阳在中。健而直。故为棘。为蒺藜。坎阳陷朋中。不能移动。如法律之固定。如桎梏之在手足。故为法律。为桎梏。</p><p>离为火。为日。为电。为中女。为甲冑。为戈兵。其于人也。为大腹。为乾卦。为鳖。为蟹。为赢。为蚌。为龟。其于木也。为科上槁。</p><p>为牝牛。 取火之明。故为日为电。中虚故为大腹。余象皆取外坚。离中拓故科上槁。经皆以艮为龟。变外坚故。</p><p>艮为山。为径路。为小石。为门阙。为果蓏。为阁寺。为指。为狗。为鼠。为黔喙之属。其于木也为坚多节。</p><p>为养。为虎。为狐。震为大涂。反之则为径路。为山。故为石。外坚故也。门阙阍寺皆象形。指能屈伸制物。与手同义。故为指。狗。虞翻云。上已有狗。当为拘字之误。按构变音句（左金）。礼曲礼若仆者降等则自下拘之。注拘取之也。释文。拘古侯反。是拘与狗音同。故通用。而其义为取。仍由手取象。狗拘亦犹龙马（右龙）羊阳之通用。不可谓龙羊之为误字也。凡经书字如此者。必有其故。详细推考。自能得其故。不必遽为改字。艮为穴。鼠穴居。故为鼠。黔喙。易林作黔啄。说反喙耶。啄家食也。马却皆谓为虎象之属，实虎约无黔者。茗啄则专属之鸟。鸟之刚在啄。鸟艮刚在上。故为黔喙。凡鸟之鸷者。无不黔啄。易林以艮为鹰檀（右鸟）雕隼。本此也。刚在外故坚多节。鼻者面之山。故又为鼻。乾为虎。艮得乾上爻。故亦为虎。狐穴居故亦为狐。</p><p>兑为泽。为少女。为巫。为口舌。为毁折。为附决。其于地也。为刚卤。为妾。为羊。</p><p>为常。为辅颊。巫以口舌用事。故为巫。上缺故为毁折。阴下附于阳。故为附。爻绝于上故为决。兑之附决。犹巽之进退也。朱仰之云。地不生物曰刚卤。按释名地不生物曰卤。左传襄三十五年楚子木使表淳卤。注淳卤蛹（左土）薄之地。盖刚者地不柔和。卤者挠（左石）确。故不生物。与毁折义合。许慎谓卤为西方卤地。非也。兑为少女故为妾。兑为羊。郑谓羊养青同通用。养炊妇。更贱于妾。似较虞作羔为近。辅颊取卦形。常九。家云西方神也。右所增象。依九家本。汉人注经。十八九皆用之。何逸之有。先儒以他本皆无。独九家有之。不敢列人。乃谨慎之意。岂知经若本无。九家何敢擅增。况证以易林及汉魏人注。几人人知之。为说经者所不可离。不得名曰逸象。经文之字。各本多寡异同者多矣。兹何足异。故拣择而从则可。谓为逸象。则名不副实。</p>',40)])])}const f=a(r,[["render",i]]);export{d as __pageData,f as default};
